<script setup>
import { ref, computed, watch } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { api, uploadFile } from '../services/api'
import { useWorkspace } from '../stores/workspace'
const props=defineProps({modelValue:Boolean,skills:{type:Array,default:()=>[]}})
const emit=defineEmits(['update:modelValue','changed'])
const s=useWorkspace(),step=ref(0),batch=ref(null),busy=ref(false),mapping=ref({}),records=ref([]),current=ref(null),synthetic=ref(null),confirmed=ref(false),allowDemo=ref(false)
const group=()=>Number(s.group)
const canProceed=computed(()=>batch.value&&batch.value.status==='preview')
function reset(){step.value=0;batch.value=null;mapping.value={};records.value=[];current.value=null;synthetic.value=null;confirmed.value=false;allowDemo.value=false}
function apply(value){batch.value=value;mapping.value={...value.mapping};records.value=JSON.parse(JSON.stringify(value.records))}
async function upload(event){const file=event.target.files?.[0];event.target.value='';if(!file)return
  if(!/\.(xlsx|xls)$/i.test(file.name)||file.size>5*1024*1024)return ElMessage.warning('请选择不超过5MB的 .xlsx 或 .xls 文件。')
  const request=new FormData();request.append('group',String(group()));request.append('file',file);busy.value=true
  try{apply(await uploadFile('imports/excel/',request));step.value=0}catch(e){ElMessage.error(e.message)}finally{busy.value=false}}
async function patch(values){busy.value=true;try{const result=await api(`imports/excel/${batch.value.id}/`,'PATCH',{group:group(),revision:batch.value.revision,...values});apply(result);return true}catch(e){ElMessage.error(e.message);return false}finally{busy.value=false}}
async function sheetChanged(index){if(!batch.value||index===batch.value.selected_sheet)return;try{await ElMessageBox.confirm('切换工作表会重新识别字段和记录，尚未保存的逐行修改将丢失。','切换工作表')}catch{return}await patch({selected_sheet:index})}
async function saveMapping(){if(await patch({mapping:mapping.value}))step.value=2}
async function aiSuggest(){if(synthetic.value===null)return ElMessage.warning('请先说明是否为合成数据。');busy.value=true
  try{const localMapping={...mapping.value};apply(await api(`imports/excel/${batch.value.id}/ai-suggest/`,'POST',{group:group(),revision:batch.value.revision,synthetic:synthetic.value},{timeout:630000}));mapping.value=localMapping;ElMessage.success('已收到真实AI表头建议，请人工核对后选择是否应用。')}
  catch(e){ElMessage.error(e.message)}finally{busy.value=false}}
function useSuggestion(){if(batch.value?.ai_status==='suggested')mapping.value={...batch.value.ai_suggestion}}
function targetChanged(row){const nurse=s.data.nurses.find(n=>n.id===row.target_id);row.expected_revision=nurse?.revision??null;row.existing=nurse?JSON.parse(JSON.stringify(nurse)):null}
function field(row,key,value){if(value===null||value===undefined||value==='')delete row.fields[key];else row.fields[key]=value}
function editRow(row){current.value=row}
async function reviewDone(){const allowed=['row_number','action','target_id','expected_revision','fields','ignored_fields','confirm_certifications'];const changes=records.value.map(row=>Object.fromEntries(allowed.map(key=>[key,row[key]])))
  if(await patch({records:changes})){current.value=null;step.value=4}}
async function confirm(){if(!confirmed.value)return ElMessage.warning('请先确认已逐条核对。');busy.value=true
  try{apply(await api(`imports/excel/${batch.value.id}/confirm/`,'POST',{group:group(),revision:batch.value.revision,confirmed:true,allow_demo_ids:allowDemo.value}));ElMessage.success('导入完成');emit('changed')}
  catch(e){const details=(e.issues||[]).map(x=>`第${x.row_number}行：${(x.messages||[]).join('；')}`).join('；');ElMessage.error(e.message+(details?' '+details:''))}finally{busy.value=false}}
watch(()=>props.modelValue,open=>{if(open)reset()})
watch(()=>s.group,()=>{emit('update:modelValue',false);reset()})
</script>
<template><el-dialog :model-value="modelValue" title="Excel智能导入护士资料" width="min(1200px,95vw)" :close-on-click-modal="false" @close="emit('update:modelValue',false)">
  <el-steps :active="batch?.status==='completed'?5:step" finish-status="success" align-center><el-step title="上传Excel"/><el-step title="字段识别"/><el-step title="档案匹配"/><el-step title="人工核对"/><el-step title="确认导入"/></el-steps>
  <div v-loading="busy" class="import-body">
    <section v-if="step===0"><h3>上传 Excel 文件</h3><p class="muted small">支持 .xlsx、.xls，最大5MB；文件首行为表头。记录将进入当前大组的待核对导入任务。</p><label class="upload-btn">选择 Excel 文件<input type="file" accept=".xlsx,.xls" @change="upload"/></label><template v-if="batch"><div class="notice"><b>{{batch.filename}}</b><p>工作表：{{batch.sheets.length}} 个 · 当前 {{batch.summary.total}} 条记录 / {{batch.headers.length}} 列</p><el-select :model-value="batch.selected_sheet" @change="sheetChanged"><el-option v-for="sheet in batch.sheets" :key="sheet.index" :value="sheet.index" :label="sheet.name+' · '+sheet.rows+'行 / '+sheet.columns+'列'"/></el-select></div></template></section>
    <section v-if="step===1&&batch"><div class="card-title"><div><h3>识别并核对字段</h3><small class="muted">当前采用本地规则；AI建议仅在实际调用成功后显示，不会直接应用。</small></div><el-button :disabled="!s.data.ai.configured" @click="aiSuggest">真实AI辅助识别表头</el-button></div><div class="actions"><span class="small">文件是否为合成数据：</span><el-radio-group v-model="synthetic" size="small"><el-radio-button :value="true">合成数据</el-radio-button><el-radio-button :value="false">真实人员资料</el-radio-button></el-radio-group><span v-if="!s.data.ai.configured" class="muted small">AI服务未配置</span><span v-if="synthetic===false" class="muted small">真实资料外发须经过医院授权。</span></div>
      <el-table :data="batch.headers.map(h=>({header:h}))" max-height="430"><el-table-column prop="header" label="Excel原始字段"/><el-table-column label="目标系统字段"><template #default="{row}"><el-select v-model="mapping[row.header]" clearable placeholder="不导入"><el-option v-for="(label,key) in batch.fields" :key="key" :value="key" :label="label"/></el-select></template></el-table-column><el-table-column label="匹配状态"><template #default="{row}"><el-tag :type="mapping[row.header]?'success':'warning'">{{mapping[row.header]?'已匹配':'待选择 / 跳过'}}</el-tag><small v-if="batch.ai_suggestion?.[row.header]" class="muted">　AI建议：{{batch.fields[batch.ai_suggestion[row.header]]}}</small></template></el-table-column></el-table><el-button v-if="batch.ai_status==='suggested'" @click="useSuggestion">应用AI建议后继续核对</el-button>
    </section>
    <section v-if="step===2&&batch"><h3>护士档案匹配</h3><p class="muted small">仅工号自动匹配；姓名相同只作为候选，不自动覆盖。可以逐行选择新增、更新、暂不导入或待核对。</p><el-table :data="records" max-height="450"><el-table-column prop="row_number" label="行号" width="70"/><el-table-column label="Excel姓名 / 工号" min-width="160"><template #default="{row}">{{row.fields.name||'未识别姓名'}} / {{row.fields.employee_id||'无工号'}}</template></el-table-column><el-table-column label="处理方式" width="155"><template #default="{row}"><el-select v-model="row.action"><el-option v-for="[value,label] in [['new','新增护士'],['update','更新现有护士'],['skip','暂不导入'],['review','待核对']]" :key="value" :value="value" :label="label"/></el-select></template></el-table-column><el-table-column label="更新目标" min-width="180"><template #default="{row}"><el-select v-if="row.action==='update'" v-model="row.target_id" filterable placeholder="选择本组护士" @change="targetChanged(row)"><el-option v-for="n in s.data.nurses" :key="n.id" :value="n.id" :label="n.name+' · '+n.employee_id"/></el-select><span v-else class="muted small">{{row.candidates.length?'同名候选 '+row.candidates.length+' 人':'—'}}</span></template></el-table-column><el-table-column label="异常" min-width="130"><template #default="{row}">{{Object.values(row.issues).join('；')||'—'}}</template></el-table-column></el-table>
    </section>
    <section v-if="step===3&&batch"><h3>逐条人工核对</h3><p class="muted small">原始Excel、系统现有值和拟保存值均可查看；空缺的Excel字段不会覆盖已有档案。独立资格必须单独确认。</p><el-table :data="records" max-height="230"><el-table-column prop="row_number" label="行号" width="70"/><el-table-column label="姓名"><template #default="{row}">{{row.fields.name||'未填写'}}</template></el-table-column><el-table-column prop="action" label="处理"/><el-table-column label="异常"><template #default="{row}">{{Object.values(row.issues).join('；')||'无'}}</template></el-table-column><el-table-column label="操作"><template #default="{row}"><el-button link type="primary" @click="editRow(row)">核对修改</el-button></template></el-table-column></el-table>
      <div v-if="current" class="review-grid section-gap"><div><h4>Excel原文</h4><pre>{{JSON.stringify(current.raw,null,2)}}</pre><h4>系统现有资料</h4><pre>{{current.existing?JSON.stringify(current.existing,null,2):'未自动匹配'}}</pre></div><div><h4>最终拟保存内容 · 第{{current.row_number}}行</h4><el-form label-position="top"><div class="form-grid"><el-form-item label="姓名"><el-input :model-value="current.fields.name" @update:model-value="v=>field(current,'name',v)"/></el-form-item><el-form-item label="工号"><el-input :model-value="current.fields.employee_id" @update:model-value="v=>field(current,'employee_id',v)"/></el-form-item><el-form-item label="护理层级"><el-select :model-value="current.fields.level" clearable @update:model-value="v=>field(current,'level',v)"><el-option v-for="n in ['N0','N1','N2','N3','N4']" :key="n" :value="n"/></el-select></el-form-item><el-form-item label="ICU年资"><el-input-number :model-value="current.fields.years" :min="0" :max="60" @update:model-value="v=>field(current,'years',v)"/></el-form-item><el-form-item label="病情评估能力能级"><el-select :model-value="current.fields.assessment_level" clearable @update:model-value="v=>field(current,'assessment_level',v)"><el-option v-for="n in 5" :key="n" :value="n" :label="n+'档'"/></el-select></el-form-item><el-form-item label="专科技能"><el-select :model-value="current.fields.skills||[]" multiple filterable @update:model-value="v=>field(current,'skills',v)"><el-option v-for="sk in props.skills.filter(item=>item.enabled).map(item=>item.name)" :key="sk" :value="sk"/></el-select></el-form-item></div><el-form-item label="带教与协作能力"><el-input :model-value="current.fields.teaching_collaboration" type="textarea" @update:model-value="v=>field(current,'teaching_collaboration',v)"/></el-form-item>
        <el-collapse><el-collapse-item title="核对其他可导入字段" name="other"><div class="form-grid">
          <el-form-item label="性别"><el-select :model-value="current.fields.gender" clearable @update:model-value="v=>field(current,'gender',v)"><el-option value="女"/><el-option value="男"/></el-select></el-form-item>
          <el-form-item label="职称"><el-input :model-value="current.fields.title" @update:model-value="v=>field(current,'title',v)"/></el-form-item>
          <el-form-item label="联系方式"><el-input :model-value="current.fields.phone" @update:model-value="v=>field(current,'phone',v)"/></el-form-item>
          <el-form-item label="所属小组"><el-select :model-value="current.fields.subgroup" clearable @update:model-value="v=>field(current,'subgroup',v)"><el-option v-for="n in 4" :key="n" :value="n" :label="'第'+n+'小组'"/></el-select></el-form-item>
          <el-form-item label="带组资格"><el-select :model-value="current.fields.is_leader" clearable @update:model-value="v=>field(current,'is_leader',v)"><el-option :value="true" label="是"/><el-option :value="false" label="否"/></el-select></el-form-item>
          <el-form-item label="基础排班类型"><el-select :model-value="current.fields.base_type" clearable @update:model-value="v=>field(current,'base_type',v)"><el-option value="rotation" label="固定轮转"/><el-option value="day" label="长期固定白班"/></el-select></el-form-item>
          <el-form-item label="排班资格"><el-select :model-value="current.fields.qualifications" multiple @update:model-value="v=>field(current,'qualifications',v)"><el-option value="A" label="A班"/><el-option value="DAY" label="白班"/><el-option value="N" label="N班"/><el-option value="TRAIN" label="培训"/></el-select></el-form-item>
          <el-form-item label="在岗状态"><el-select :model-value="current.fields.status" clearable @update:model-value="v=>field(current,'status',v)"><el-option value="active" label="在岗"/><el-option value="paused" label="停排"/><el-option value="left" label="离职"/></el-select></el-form-item>
          <el-form-item label="生效日期"><el-date-picker :model-value="current.fields.effective_from" value-format="YYYY-MM-DD" @update:model-value="v=>field(current,'effective_from',v)"/></el-form-item>
          <el-form-item label="备注"><el-input :model-value="current.fields.notes" type="textarea" @update:model-value="v=>field(current,'notes',v)"/></el-form-item>
          <el-form-item label="特殊排班限制"><el-input :model-value="current.fields.special_restrictions" type="textarea" @update:model-value="v=>field(current,'special_restrictions',v)"/></el-form-item>
        </div><p class="muted small">清空控件表示本次不覆盖该字段；如需将人员设为待分组，可在人员档案中操作。</p></el-collapse-item></el-collapse>
        <h4>独立护理资格（须明确技能和有效期）</h4><div v-for="(cert,i) in (current.fields.certifications||[])" :key="i" class="actions"><el-input v-model="cert.name" placeholder="技能名称" style="width:150px"/><el-date-picker v-model="cert.expires_on" value-format="YYYY-MM-DD" placeholder="有效期"/><el-button link type="danger" @click="current.fields.certifications.splice(i,1)">移除</el-button></div><el-button size="small" @click="current.fields.certifications ||= [];current.fields.certifications.push({name:'',expires_on:''})">添加独立资质</el-button><el-checkbox v-if="current.fields.certifications?.length" v-model="current.confirm_certifications">已核实独立资格及有效期</el-checkbox>
        <div v-if="Object.keys(current.issues).length"><h4>暂不导入的异常字段</h4><el-checkbox-group v-model="current.ignored_fields"><el-checkbox v-for="(message,key) in current.issues" :key="key" :value="key">{{batch.fields[key]}}：{{message}}</el-checkbox></el-checkbox-group></div></el-form></div></div>
    </section>
    <section v-if="step===4&&batch"><h3>{{batch.status==='completed'?'导入结果':'确认导入'}}</h3><div class="import-summary"><span>总记录 {{batch.summary.total}}</span><span>新增 {{batch.summary.new}}</span><span>更新 {{batch.summary.update}}</span><span>待核对 {{batch.summary.review}}</span><span>跳过 {{batch.summary.skip}}</span><span>异常 {{batch.summary.errors}}</span></div><template v-if="batch.status==='preview'"><el-checkbox v-model="allowDemo">允许缺工号的新合成护士生成 DEMO 演示工号</el-checkbox><br/><el-checkbox v-model="confirmed">已逐条核对原文、匹配对象和拟保存内容</el-checkbox><p class="muted small">导入将使用事务；存在未处理的异常时不会保存任何护士档案。</p></template><el-table v-else :data="batch.result"><el-table-column prop="row_number" label="Excel行号"/><el-table-column prop="action" label="处理"/><el-table-column prop="status" label="结果"/><el-table-column prop="employee_id" label="工号"/></el-table></section>
  </div><template #footer><el-button @click="emit('update:modelValue',false)">关闭</el-button><el-button v-if="step>0&&batch?.status==='preview'" @click="step--">上一步</el-button><el-button v-if="step===0" type="primary" :disabled="!canProceed" @click="step=1">下一步</el-button><el-button v-if="step===1" type="primary" :loading="busy" @click="saveMapping">保存映射并继续</el-button><el-button v-if="step===2" type="primary" @click="step=3">下一步</el-button><el-button v-if="step===3" type="primary" :loading="busy" @click="reviewDone">保存核对结果</el-button><el-button v-if="step===4&&batch?.status==='preview'" type="primary" :disabled="!confirmed" :loading="busy" @click="confirm">确认导入</el-button></template>
</el-dialog></template>
<style scoped>
.import-body{min-height:300px;padding:20px 8px}.upload-btn{display:inline-flex;padding:8px 16px;border-radius:6px;background:#0869ef;color:white;cursor:pointer;font-size:13px}.upload-btn input{display:none}.review-grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}.review-grid>div{min-width:0;border:1px solid #e1ebf6;border-radius:8px;padding:14px}.review-grid pre{white-space:pre-wrap;word-break:break-word;font-size:11px;max-height:200px;overflow:auto;background:#f5f9fe;padding:10px}.import-summary{display:flex;flex-wrap:wrap;gap:12px;margin:20px 0}.import-summary span{padding:10px 14px;background:#eef6ff;border-radius:6px;font-size:13px}
</style>
